class RemoteBackend:
    def __init__(self):
        self.state = {}
        self.locked_by = None

    def lock(self, who):
        if self.locked_by is not None:
            raise RuntimeError(f"state locked by {self.locked_by}")
        self.locked_by = who

    def unlock(self, who):
        if self.locked_by == who:
            self.locked_by = None

    def apply(self, who, resource, attrs):
        self.lock(who)
        self.state[resource] = attrs
        self.unlock(who)


backend = RemoteBackend()
backend.apply("alice", "aws_instance.web", {"instance_type": "t2.micro"})

try:
    backend.locked_by = "bob"
    backend.apply("alice", "aws_instance.db", {"engine": "postgres"})
except RuntimeError as exc:
    print("error:", exc)

backend.unlock("bob")
backend.apply("alice", "aws_instance.db", {"engine": "postgres"})
print(sorted(backend.state))
